from typing import List
class Solution:
  def minimumEffort(self, tasks: List[List[int]]) -> int:
    tasks.sort(key=lambda x: x[1]-x[0], reverse=True)
    s=0
    r=0
    for a,m in tasks:
      r=max(r,s+m)
      s+=a
    return r

sol=Solution()
print(sol.minimumEffort(tasks = [[1,2],[2,4],[4,8]]))
